import re
import unicodedata

# Characters that NFKD does not decompose; map them to ASCII equivalents.
_EXTRA = {
    'ø': 'o',
    'ł': 'l',
    'đ': 'd',
    'ð': 'd',
    'þ': 'th',
    'ß': 'ss',
}


def slugify(s):
    s = unicodedata.normalize('NFKD', s.lower())
    out = []
    for ch in s:
        # Drop combining marks left over from decomposition (e.g. õ -> o + ̃).
        if unicodedata.category(ch).startswith('M'):
            continue
        if ch in _EXTRA:
            out.append(_EXTRA[ch])
        elif ch.isalnum():
            out.append(ch)
        else:
            out.append('-')
    return re.sub(r'-{2,}', '-', ''.join(out)).strip('-')

import unicodedata


def slugify(s):
    s = unicodedata.normalize('NFKD', s).lower()
    s = ''.join(ch for ch in s if not unicodedata.combining(ch))
    parts = []
    current = []
    for ch in s:
        if ch.isalnum():
            current.append(ch)
        elif current:
            parts.append(''.join(current))
            current = []
    if current:
        parts.append(''.join(current))
    return '-'.join(parts)
